(()=>{'use strict';const form=document.querySelector('#public-request'),steps=[...form.querySelectorAll('[data-step]')],status=document.querySelector('#form-status');let step=0;const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fields={realEstate:'<label>Operaciones ofrecidas (comprar / vender / alquilar / tasaciones)<textarea name="operations"></textarea></label><p>Hasta 3 propiedades iniciales. Solo datos reales que quieras publicar.</p>',service:'<p>Trabajos realizados · Fotos antes, durante y después.</p>',commerce:'<p>Productos destacados · Foto, descripción, precio y promoción.</p>',other:'<label>Información específica de tu rubro<textarea name="customModule"></textarea></label>'};function details(){const t=form.elements.type.value;document.querySelector('#special-fields').innerHTML=fields[t]+(t==='other'?'':Array.from({length:3},(_,i)=>`<details><summary>${{realEstate:'Propiedad',service:'Trabajo',commerce:'Producto'}[t]} ${i+1} · Opcional</summary><label>Título<input name="item${i}_title"></label><label>Descripción<textarea name="item${i}_description"></textarea></label><label>Foto<input type="file" name="item${i}_photo" accept="image/png,image/jpeg,image/webp"></label>${t==='realEstate'?['Barrio','Precio','Dormitorios','Baños','Metros cuadrados'].map((n,j)=>`<label>${n}<input name="item${i}_${['area','price','bedrooms','bathrooms','squareMeters'][j]}" ${j>1?'type="number" min="0"':''}></label>`).join(''):t==='commerce'?`<label>Precio<input name="item${i}_price"></label><label>Promoción<input name="item${i}_promotion"></label>`:['before','during','after'].map((k,j)=>`<label>${['Antes','Durante','Después'][j]}<input type="file" name="item${i}_${k}" accept="image/png,image/jpeg,image/webp"></label>`).join('')}</details>`).join(''))}form.elements.type.onchange=details;
function valid(){for(const el of steps[step].querySelectorAll('input,select,textarea'))if(!el.reportValidity())return false;if(step===0&&!form.elements.logo.files.length&&!form.elements.noLogo.checked){status.textContent='Agregá logo/foto o indicá que querés coordinar la imagen.';return false}return true}function show(){steps.forEach((x,i)=>{x.hidden=i!==step;x.disabled=i!==step});document.querySelectorAll('.progress span').forEach((x,i)=>x.classList.toggle('current',i===step));document.querySelector('#back').hidden=step===0;document.querySelector('#forward').hidden=step===3;status.textContent='';if(step===3){document.querySelector('#summary').innerHTML=['name','subcategory','area','phone','services'].map(k=>`<p>${esc(form.elements[k].value)}</p>`).join('')}steps[step].querySelector('input,select')?.focus()}
document.querySelector('#back').onclick=()=>{step--;show()};document.querySelector('#forward').onclick=()=>{if(valid()){step++;show()}};function readFile(file){return new Promise((resolve,reject)=>{const r=new FileReader;r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}async function collect(){const b={id:crypto.randomUUID(),status:'received',schemaVersion:1,photos:[],historyPhotos:[],modules:{},createdAt:new Date().toISOString()};for(const el of form.elements){if(!el.name||el.type==='file'||el.type==='checkbox')continue;b[el.name]=el.value.trim()}b.category={realEstate:'Inmobiliarias',commerce:'Comercio',service:'Servicios / Oficios',other:'Otro'}[b.type];b.services=b.services.split('\n').filter(Boolean);b.advice=b.advice?[{title:'Material para revisar',text:b.advice}]:[];b.noLogo=form.elements.noLogo.checked;let total=0;for(const el of form.querySelectorAll('input[type=file]')){const files=[...el.files];if((el.name==='photos'||el.name==='historyPhotos')&&files.length>10)throw Error('Máximo 10 fotos por galería.');for(const file of files){if(file.size>2*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Imágenes JPG, PNG o WebP de hasta 2 MB.');total+=file.size}if(total>30*1024*1024)throw Error('Usá imágenes más livianas: máximo 30 MB en total.');const data=await Promise.all(files.map(readFile));b[el.name]=el.multiple?data:data[0]||''}const key={realEstate:'properties',commerce:'products',service:'works'}[b.type];if(key){b.modules[key]=Array.from({length:3},(_,i)=>{const item={};for(const k of ['title','description','photo','area','price','bedrooms','bathrooms','squareMeters','promotion','before','during','after']){item[k]=b[`item${i}_${k}`]||'';delete b[`item${i}_${k}`]}return item}).filter(p=>p.title)}return b}function download(b){const u=URL.createObjectURL(new Blob([JSON.stringify(b,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='solicitud-revista-montevideo.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}document.querySelector('#download-request').onclick=async()=>{if(!valid())return;try{download(await collect());status.textContent='Solicitud descargada. Adjuntá el archivo en WhatsApp para enviarlo a la revista.'}catch(e){status.textContent=e.message}};form.onsubmit=async e=>{e.preventDefault();if(!valid())return;try{const b=await collect();const msg=['Hola Revista Montevideo, quiero pedir mi espacio.',`Negocio: ${b.name}`,`Rubro: ${b.category} / ${b.subcategory}`,`Zona: ${b.area}`,`Contacto: ${b.phone}`,`Servicios: ${b.services.join(', ')}`,'Autorizo preparar mi ficha, sujeta a revisión.','Adjuntaré el archivo de solicitud con las imágenes.'].join('\n');window.location.href='https://wa.me/59891685800?text='+encodeURIComponent(msg);status.textContent='Enviá el mensaje y adjuntá el archivo descargado en WhatsApp. La ficha todavía no está publicada.'}catch(e){status.textContent=e.message}};show()})();
